Item.method_code:
Innovator inn = this.getInnovator();
string aml = this.getProperty("aml", "");

// AMLが空の場合はエラーを返す
if (string.IsNullOrEmpty(aml))
{
    return inn.newError("AMLが指定されていません");
}

try
{
    // Administrators権限を付与して処理を実行
    using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
    {
        // AMLを実行
        Item result = inn.applyAML(aml);
        
        if (result.isError())
        {
            return result;
        }
        
        return result;
    }
}
catch (Exception ex)
{
    return inn.newError("エラーが発生しました: " + ex.Message);
}
